4:#[macro_export]
5:macro_rules! gpu_buffers {
6:    (
7:        $(#[$struct_meta:meta])*
8:        $vis:vis struct $name:ident {
9:            $(
10:                $(#[$field_meta:meta])*
11:                $field_vis:vis $field:ident : $kind:ident < { $dim:expr } >
12:            ),* $(,)?
13:        }
14:    ) => {
15:        $(#[$struct_meta])*
16:        $vis struct $name {
17:            $(
18:                $(#[$field_meta])*
19:                $field_vis $field : $crate::tensor:: $kind < { $dim } >,
20:            )*
21:        }
23:        impl $name {
24:            $vis fn new(
25:                ctx: &$crate::tensor::DeviceContext,
26:                batch_size: usize,
27:            ) -> ::anyhow::Result<Self> {
28:                Ok(Self {
29:                    $(
30:                        $field: $crate::gpu_buffers!(@alloc ctx, batch_size, $kind, $dim),
31:                    )*
32:                })
33:            }
35:            $vis fn set_batch_size(&mut self, bs: usize) {
36:                $(
37:                    $crate::gpu_buffers!(@set_bs self, bs, $field, $kind);
38:                )*
39:            }
40:        }
41:    };
43:    (@alloc $ctx:ident, $bs:ident, GpuTensor, $dim:expr) => {
44:        $crate::tensor::GpuTensor::<{ $dim }>::zeros($ctx, $bs)?
45:    };
46:    (@alloc $ctx:ident, $bs:ident, GpuRawSlice, $dim:expr) => {
47:        $crate::tensor::GpuRawSlice::<{ $dim }>::zeros($ctx, $bs)?
48:    };
49:    (@alloc $ctx:ident, $bs:ident, GpuRawSliceI32, $dim:expr) => {
50:        $crate::tensor::GpuRawSliceI32::<{ $dim }>::zeros($ctx, $bs)?
51:    };
53:    (@set_bs $self:ident, $bs:ident, $field:ident, GpuTensor) => {
54:        $self.$field.seq_len = $bs;
55:    };
56:    (@set_bs $self:ident, $bs:ident, $field:ident, GpuRawSlice) => {
57:        $self.$field.batch_size = $bs;
58:    };
59:    (@set_bs $self:ident, $bs:ident, $field:ident, GpuRawSliceI32) => {
60:        $self.$field.batch_size = $bs;
61:    };
