24	        .chain(default_paths.iter().map(PathBuf::from))
25	        .collect();
26	    for root in &roots {
27	        for check in check_files {
28	            let found = root.join(check);
29	            if found.is_file() {
30	                if let Some(env_root) = &env_root
31	                    && env_root != root
32	                {
33	                    println!(
34	                        "cargo:warning={provider}: ${env_var} ({}) contains none of \
35	                         {check_files:?}; using {} instead",
36	                        env_root.display(),
37	                        root.display()
38	                    );
39	                }
40	                return (root.clone(), found);
41	            }
42	        }
43	    }
44	    panic!(
45	        "{provider} build error: none of {check_files:?} found. \
46	         Looked at `${env_var}` ({env_status}) and default paths {default_paths:?}. \
47	         Hint: install the provider headers or set `{env_var}` to their install root.",
48	        env_status = env_root
