79	/// Profile one user range with CUPTI Range Profiler.
80	///
81	/// # Safety
82	///
83	/// `context` must be a live CUDA `CUcontext` for `device_index`, and the
84	/// callbacks must only launch work on that context while this function runs.
85	pub unsafe fn profile_range_with_prepare<'a>(
86	    context: CuContext,
87	    device_index: usize,
88	    range_name: &str,
89	    metric_names: &[&str],
90	    prepare: Option<&'a mut dyn FnMut() -> Result<(), String>>,
91	    launch: &'a mut dyn FnMut() -> Result<(), String>,
92	) -> Result<Vec<f64>, CuptiProfilerError> {
93	    let range_name =
94	        CString::new(range_name).map_err(|err| CuptiProfilerError::new(err.to_string()))?;
95	    let metric_names: Vec<CString> = metric_names
96	        .iter()
97	        .map(|name| CString::new(*name).map_err(|err| CuptiProfilerError::new(err.to_string())))
98	        .collect::<Result<_, _>>()?;
99	    let metric_ptrs: Vec<*const c_char> = metric_names.iter().map(|name| name.as_ptr()).collect();
100	    let mut values = vec![0.0; metric_ptrs.len()];
101	    let mut error = vec![0; 4096];
102	    let mut state = CallbackState {
103	        prepare,
104	        launch,
105	        error: None,
106	    };
107	    let prepare_fn = if state.prepare.is_some() {
108	        Some(prepare_trampoline as unsafe extern "C" fn(*mut c_void) -> c_int)
109	    } else {
110	        None
111	    };
112	
113	    let status = unsafe {
114	        pegainfer_cupti_profile_range(
115	            context,
116	            device_index,
117	            range_name.as_ptr(),
118	            metric_ptrs.as_ptr(),
119	            metric_ptrs.len(),
120	            prepare_fn,
121	            Some(launch_trampoline),
122	            (&raw mut state).cast::<c_void>(),
123	            values.as_mut_ptr(),
124	            values.len(),
125	            error.as_mut_ptr(),
126	            error.len(),
127	        )
128	    };
129	
130	    if status == 0 {
131	        return Ok(values);
132	    }
133	
134	    let ffi_error = unsafe { CStr::from_ptr(error.as_ptr()) }
135	        .to_string_lossy()
136	        .into_owned();
137	    let callback_error = state.error.take();
138	    match callback_error {
139	        Some(callback_error) if !ffi_error.is_empty() => Err(CuptiProfilerError::new(format!(
140	            "{ffi_error}; callback error: {callback_error}"
141	        ))),
142	        Some(callback_error) => Err(CuptiProfilerError::new(callback_error)),
143	        None => Err(CuptiProfilerError::new(ffi_error)),
144	    }
145	}
